WITH with_windows AS (SELECT id, channel, starts_on, ends_on, SUM(discount_pct) OVER w_recent AS last7_sum_discount_pct, MAX(discount_pct) OVER w_recent AS last7_max_discount_pct, AVG(discount_pct) OVER w_recent AS last7_avg_discount_pct, NTILE(4) OVER (ORDER BY discount_pct, id) AS discount_pct_bucket FROM promotions WINDOW w_recent AS (PARTITION BY promo_code ORDER BY discount_pct, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)) SELECT id, channel, starts_on, ends_on, last7_sum_discount_pct, last7_max_discount_pct, last7_avg_discount_pct FROM with_windows ORDER BY channel NULLS FIRST
